PREFIX brick: <http://brickschema.org ontology/2023#>
PREFIX ref: <urn:ref:>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?zone ?zoneIRI ?sensor ?sensorIRI ?tsid WHERE {
  ?z a brick:Zone_F3_Z01 .
}

SELECT ?sensor ?slbl ?tsid WHERE {
  ?sensor rdfs:label ?slbl .
  ?sensor ref:hasExternalReference ?t .
  ?t ref:hasTimeseriesId ?tsid .
  FILTER regex(?slbl, "Zone.*Temperature|Temperature.*Zone") .
} LIMIT 60

SELECT ?p ?slbl ?tsid WHERE {
  ?p rdfs:label ?slbl .
  ?p ref:hasExternalReference ?t .
  ?t ref:hasTimeseriesId ?tsid .
  FILTER regex(?slbl, "F3") .
} LIMIT 60

